\set ON_ERROR_STOP on
-- backyrd:authorization-positive
-- backyrd:authorization-negative
begin;
create function pg_temp.assert(p_ok boolean,p_message text) returns void language plpgsql as $$ begin if p_ok is not true then raise exception 'scoped knowledge failed: %',p_message;end if;end $$;
create function pg_temp.id(p text) returns uuid language sql immutable as $$ select (substr(md5(p),1,8)||'-'||substr(md5(p),9,4)||'-4'||substr(md5(p),14,3)||'-8'||substr(md5(p),18,3)||'-'||substr(md5(p),21,12))::uuid $$;
create function pg_temp.expect_error(p_sql text,p_state text,p_message text) returns void language plpgsql as $$ declare code text;begin begin execute p_sql;exception when others then get stacked diagnostics code=returned_sqlstate;if code=p_state then return;end if;raise exception '%: received %',p_message,code;end;raise exception '%: unexpected success',p_message;end $$;
select set_config('app.world_knowledge_founder_authoring_enabled','on',true);
create temporary table experience_fixture(value jsonb);
insert into experience_fixture values ('{"contractVersion":"backyrd.world-knowledge.experience-profile@1.0","category":"SPORT","properties":[],"areas":[{"id":"hall","kind":"BOULDER_AREA","name":"Synthetic boulder area","properties":[]}],"offers":[{"id":"boulder","kind":"BOULDERING","name":"Synthetic bouldering","areaIds":["hall"],"properties":[{"key":"sport.rental","label":null,"state":"KNOWN","value":true,"conditions":{"weekdays":[],"dayparts":[],"event":null,"validFrom":null,"validUntil":null}},{"key":"sport.registration","label":null,"state":"KNOWN","value":true,"conditions":{"weekdays":[],"dayparts":[],"event":null,"validFrom":null,"validUntil":null}},{"key":"sport.induction","label":null,"state":"KNOWN","value":false,"conditions":{"weekdays":[],"dayparts":[],"event":null,"validFrom":null,"validUntil":null}},{"key":"sport.equipment","label":null,"state":"KNOWN","value":"Kletterschuhe","conditions":{"weekdays":[],"dayparts":[],"event":null,"validFrom":null,"validUntil":null}}],"prices":[],"schedule":[],"validFrom":null,"validUntil":null}],"reviewed":true}'::jsonb);
do $$ declare profile jsonb;begin for profile in select value from jsonb_array_elements('[{"contractVersion":"backyrd.world-knowledge.experience-profile@1.0","category":"RESTAURANT","properties":[],"areas":[{"id":"a0","kind":"INDOOR","name":"Gastraum","properties":[]},{"id":"a1","kind":"TERRACE","name":"Terrasse","properties":[]},{"id":"a2","kind":"PRIVATE_ROOM","name":"Privater Raum","properties":[]}],"offers":[{"id":"o0","kind":"LUNCH","name":"Mittagessen","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o1","kind":"DINNER","name":"Abendessen","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o2","kind":"APERITIF","name":"Apéro","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o3","kind":"BREAKFAST","name":"Frühstück","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o4","kind":"PRIVATE_CELEBRATION","name":"Private Feier","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null}],"reviewed":true},{"contractVersion":"backyrd.world-knowledge.experience-profile@1.0","category":"ZOO","properties":[],"areas":[{"id":"a0","kind":"OUTDOOR","name":"Außengelände","properties":[]},{"id":"a1","kind":"INDOOR","name":"Tierhaus","properties":[]},{"id":"a2","kind":"PLAYGROUND","name":"Spielplatz","properties":[]},{"id":"a3","kind":"REST_AREA","name":"Ruhebereich","properties":[]},{"id":"a4","kind":"CAFE","name":"Gastronomiebereich","properties":[]}],"offers":[{"id":"o0","kind":"VISIT","name":"Zoobesuch","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o1","kind":"GUIDED_TOUR","name":"Führung","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o2","kind":"ANIMAL_OBSERVATION","name":"Tierbeobachtung","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o3","kind":"EVENT","name":"Veranstaltung","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o4","kind":"GASTRONOMY","name":"Gastronomie","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null}],"reviewed":true},{"contractVersion":"backyrd.world-knowledge.experience-profile@1.0","category":"MUSEUM","properties":[],"areas":[{"id":"a0","kind":"EXHIBITION","name":"Ausstellungsraum","properties":[]},{"id":"a1","kind":"WORKSHOP","name":"Workshopraum","properties":[]},{"id":"a2","kind":"OUTDOOR","name":"Außenbereich","properties":[]},{"id":"a3","kind":"CAFE","name":"Cafébereich","properties":[]}],"offers":[{"id":"o0","kind":"PERMANENT_EXHIBITION","name":"Dauerausstellung","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o1","kind":"SPECIAL_EXHIBITION","name":"Sonderausstellung","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o2","kind":"GUIDED_TOUR","name":"Führung","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o3","kind":"WORKSHOP","name":"Workshop","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o4","kind":"SELF_GUIDED_VISIT","name":"Besuch ohne Führung","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o5","kind":"CAFE","name":"Café","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null}],"reviewed":true},{"contractVersion":"backyrd.world-knowledge.experience-profile@1.0","category":"SPORT","properties":[],"areas":[{"id":"a0","kind":"BOULDER_AREA","name":"Boulderbereich","properties":[]},{"id":"a1","kind":"CLIMBING_AREA","name":"Kletterbereich","properties":[]},{"id":"a2","kind":"TRAINING_AREA","name":"Trainingsbereich","properties":[]},{"id":"a3","kind":"CHILDREN_AREA","name":"Kinderbereich","properties":[]},{"id":"a4","kind":"CHANGING_ROOM","name":"Garderobe","properties":[]},{"id":"a5","kind":"CAFE","name":"Cafébereich","properties":[]},{"id":"a6","kind":"OUTDOOR","name":"Aussenbereich","properties":[]}],"offers":[{"id":"o0","kind":"BOULDERING","name":"Bouldern","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o1","kind":"CLIMBING","name":"Klettern","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o2","kind":"TRAINING","name":"Freies Training","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o3","kind":"COURSE","name":"Kurs / Einführung","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o4","kind":"CHILDREN_COURSE","name":"Kinderkurs","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o5","kind":"MOVEMENT_PLAY","name":"Bewegungslandschaft für Kinder","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o6","kind":"CAFE","name":"Café / Bistro","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null}],"reviewed":true},{"contractVersion":"backyrd.world-knowledge.experience-profile@1.0","category":"BAR","properties":[],"areas":[{"id":"a0","kind":"INDOOR","name":"Barraum","properties":[]},{"id":"a1","kind":"TERRACE","name":"Terrasse","properties":[]},{"id":"a2","kind":"LOUNGE","name":"Lounge","properties":[]},{"id":"a3","kind":"EVENT_AREA","name":"Veranstaltungsbereich","properties":[]}],"offers":[{"id":"o0","kind":"DRINKS","name":"Getränke","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o1","kind":"APERITIF","name":"Apéro / Snacks","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o2","kind":"FULL_MEAL","name":"Vollständige Mahlzeiten","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o3","kind":"MUSIC_EVENT","name":"Musikveranstaltung","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null},{"id":"o4","kind":"PRIVATE_CELEBRATION","name":"Private Feier","areaIds":[],"properties":[],"prices":[],"schedule":[],"validFrom":null,"validUntil":null}],"reviewed":true}]'::jsonb) loop if not world_knowledge_private.experience_profile_valid_v1(profile) then raise exception 'category template failed: %',profile->>'category';end if;end loop;end $$;
select pg_temp.assert(world_knowledge_private.experience_profile_valid_v1((select value from experience_fixture)),'valid profile rejected');
select pg_temp.assert(not world_knowledge_private.experience_profile_valid_v1(jsonb_set((select value from experience_fixture),'{reviewed}','false')),'unreviewed accepted');
select pg_temp.assert(not world_knowledge_private.experience_profile_valid_v1(jsonb_set((select value from experience_fixture),'{offers,0,areaIds}','["missing"]')),'dangling area accepted');
select pg_temp.assert(not world_knowledge_private.experience_profile_valid_v1(jsonb_set((select value from experience_fixture),'{offers,0,properties,0,key}','"unexpected.key"')),'unknown property accepted');
select pg_temp.assert(not world_knowledge_private.experience_profile_valid_v1(jsonb_set((select value from experience_fixture),'{offers,0,validFrom}','"2026-02-30"')),'invalid date accepted');
select pg_temp.assert(not world_knowledge_private.experience_profile_valid_v1(jsonb_set((select value from experience_fixture),'{offers,0,validFrom}','"2027-01-01"')||jsonb_build_object('invalidExtra',1)),'extra top field accepted');
select pg_temp.assert(world_knowledge_private.attribute_value_valid_v6('backyrd.world-knowledge.registry@2.4','experience.profile','UNKNOWN','null'),'explicit unknown lost');
select pg_temp.assert((select registry_hash='c3016e37bc0bb178c390a01a55cf69fa8d8f748593e1a794d2b2f9d84e513cc3' from world_knowledge_private.registry_releases where registry_version='backyrd.world-knowledge.registry@2.3'),'historical registry changed');
do $$ declare actor text;begin
 foreach actor in array array['sport-catalog-owner','sport-catalog-admin','sport-catalog-stranger'] loop
  insert into auth.users(instance_id,id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values('00000000-0000-0000-0000-000000000000',pg_temp.id(actor),'authenticated','authenticated',actor||'@test.invalid','','{}','{}',clock_timestamp(),clock_timestamp());
  insert into public.profiles(id,is_admin) values(pg_temp.id(actor),actor='sport-catalog-admin') on conflict(id) do update set is_admin=excluded.is_admin;
 end loop;
 insert into public.spots(id,name,lat,lng,status,city,owner_id,data_origin) values(pg_temp.id('sport-catalog-restaurant'),'Synthetic boulder facility',47.1,8.1,'approved','Basel',pg_temp.id('sport-catalog-owner'),'TEST');
end $$;
grant select on experience_fixture to authenticated,service_role;
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id('sport-catalog-owner')::text,true);
select set_config('request.jwt.claim.role','authenticated',true);
select pg_temp.assert((public.world_owner_submit_claim_v1(pg_temp.id('sport-catalog-restaurant'),'experience.profile','KNOWN_VALUE',(select value from experience_fixture),clock_timestamp(),null,null,'PUBLIC',null,'sport-catalog-owner-write')->>'verificationMethod')='OWNER_CONFIRMED','owner write denied');
select pg_temp.assert(public.world_product_authoring_detail_v1(pg_temp.id('sport-catalog-restaurant'))#>'{answers,experience.profile,value}'=(select value from experience_fixture),'owner saved value did not round-trip');
select set_config('request.jwt.claim.sub',pg_temp.id('sport-catalog-stranger')::text,true);
select pg_temp.expect_error(format('select public.world_owner_submit_claim_v1(%L,%L,%L,%L::jsonb,clock_timestamp(),null,null,%L,null,%L)',pg_temp.id('sport-catalog-restaurant'),'experience.profile','KNOWN_VALUE',(select value::text from experience_fixture),'PUBLIC','sport-catalog-foreign-write'),'42501','foreign owner write accepted');
select pg_temp.expect_error(format('select public.world_product_authoring_detail_v1(%L)',pg_temp.id('sport-catalog-restaurant')),'42501','foreign detail accepted');
select set_config('request.jwt.claim.sub',pg_temp.id('sport-catalog-admin')::text,true);
select pg_temp.assert((public.world_admin_submit_claim_v1(pg_temp.id('sport-catalog-restaurant'),'identity.name','KNOWN_VALUE','"Synthetic scoped restaurant"',clock_timestamp(),null,null,'PUBLIC',null,'sport-catalog-admin-name')->>'verificationMethod')='ADMIN_CONFIRMED','admin write denied');
select pg_temp.assert((public.world_admin_submit_claim_v1(pg_temp.id('sport-catalog-restaurant'),'experience.profile','KNOWN_VALUE',(select value from experience_fixture),clock_timestamp(),null,null,'PUBLIC',null,'sport-catalog-admin-profile')->>'verificationMethod')='ADMIN_CONFIRMED','admin scoped write denied');
reset role;
set local role service_role;
create temporary table experience_manifest as select public.world_shadow_rebuild_spot_v1(pg_temp.id('sport-catalog-restaurant'),clock_timestamp()+interval '1 second','FULL','sport-catalog-rebuild') payload;
reset role;
select pg_temp.assert((select payload#>>'{worldSnapshot,registryVersion}'='backyrd.world-knowledge.registry@2.4' from experience_manifest),'new registry missing from snapshot');
select pg_temp.assert((select (world_knowledge_private.product_decision_projection_v1(payload->'worldSnapshot')->'facts') @> '[{"key":"experience.profile","hardConstraintAuthorized":true}]' from experience_manifest),'scoped knowledge missing from decision projection');
select pg_temp.assert((select (world_knowledge_private.validate_resolution_manifest_v1((payload->>'manifestId')::uuid)->>'manifestHash')=payload->>'manifestHash' from experience_manifest),'manifest binding invalid');
select pg_temp.assert(not has_function_privilege('anon','public.world_product_owner_submit_claim_v1(uuid,text,text,jsonb,timestamptz,timestamptz,timestamptz,text,uuid,text)','execute'),'anonymous write granted');
select pg_temp.assert(not has_function_privilege('authenticated','world_knowledge_private.submit_authoritative_claim_v5(text,uuid,text,text,jsonb,timestamptz,timestamptz,timestamptz,text,uuid,text)','execute'),'private writer exposed');
select pg_temp.assert(not has_function_privilege('authenticated','world_knowledge_private.experience_profile_valid_v1(jsonb)','execute'),'private validator exposed');
select pg_temp.assert(not has_table_privilege('authenticated','world_knowledge_private.claims','SELECT,INSERT,UPDATE,DELETE'),'private ledger exposed');
select pg_temp.assert((select relrowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='world_knowledge_private' and c.relname='claims'),'RLS lost');
select pg_temp.assert(world_knowledge_private.text_requires_shadow_v1('experience.profile',jsonb_set((select value from experience_fixture),'{areas,0,name}','"illegal content"')),'moderation bypass');
rollback;
